import express, { Express } from 'express';
import { Product } from '../domain/entities/Product';
import { InMemoryProductRepository } from './repositories/InMemoryProductRepository';
import { InMemoryOrderRepository } from './repositories/InMemoryOrderRepository';
import { StockManager } from '../domain/services/StockManager';
import { PlaceOrderUseCase } from '../application/usecases/PlaceOrderUseCase';
import { CancelOrderUseCase } from '../application/usecases/CancelOrderUseCase';
import { UpdateOrderStatusUseCase } from '../application/usecases/UpdateOrderStatusUseCase';
import { ListOrdersByStatusUseCase } from '../application/usecases/ListOrdersByStatusUseCase';
import { GetStockLevelsUseCase } from '../application/usecases/GetStockLevelsUseCase';
import { OrderController } from './controllers/OrderController';

export function createApp(): Express {
  const app = express();
  app.use(express.json());

  const productRepository = new InMemoryProductRepository();
  const orderRepository = new InMemoryOrderRepository();
  const stockManager = new StockManager();

  initializeProducts(productRepository);

  const placeOrderUseCase = new PlaceOrderUseCase(orderRepository, productRepository, stockManager);
  const cancelOrderUseCase = new CancelOrderUseCase(orderRepository, productRepository, stockManager);
  const updateOrderStatusUseCase = new UpdateOrderStatusUseCase(orderRepository);
  const listOrdersByStatusUseCase = new ListOrdersByStatusUseCase(orderRepository);
  const getStockLevelsUseCase = new GetStockLevelsUseCase(productRepository);

  const orderController = new OrderController(
    placeOrderUseCase,
    cancelOrderUseCase,
    updateOrderStatusUseCase,
    listOrdersByStatusUseCase,
    getStockLevelsUseCase
  );

  app.post('/orders', orderController.placeOrder);
  app.delete('/orders/:orderId', orderController.cancelOrder);
  app.patch('/orders/:orderId/status', orderController.updateOrderStatus);
  app.get('/orders', orderController.listOrdersByStatus);
  app.get('/products/stock', orderController.getStockLevels);

  return app;
}

function initializeProducts(repository: InMemoryProductRepository): void {
  const products = [
    new Product('prod-001', 'Laptop', 5),
    new Product('prod-002', 'Mouse', 50),
    new Product('prod-003', 'Keyboard', 30),
    new Product('prod-004', 'Monitor', 10),
    new Product('prod-005', 'USB Cable', 100)
  ];

  for (const product of products) {
    repository.add(product);
  }
}

